export const fossilObject=id=>fossilObjects.find(o=>o.id===id)||null;
export const fossilDetail=(id,detail)=>fossilObject(id)?.details.find(d=>d.id===detail)||null;
export const fossilTeaching='Fossils are remains or traces of past life preserved in rock or other geological deposits. A body fossil preserves something from a body, such as a shell or bone. A trace fossil preserves a mark of activity, such as a footprint. Not every mark in rock came from life.';
export const fossilComparison='Our two photographs can help us compare a preserved body form with a preserved activity mark. Their source labels help us name that difference. A close view and the full view are one source, not independent confirmation. A pin from the surrounding rock does not make every line a fossil. These two pictures do not tell us the animals’ original living colors or sounds, their exact ages, or that they lived together.';
export const fossilScale='These photos are not at the same scale. Do not compare the fossils’ real sizes from these boxes.';
